def bootstrap_and_search(pc):
    if not pc.has_index("quickstart"):
        pc.create_index_for_model(
            name="quickstart",
            cloud="aws",
            region="us-east-1",
            embed={"model": "llama-text-embed-v2", "field_map": {"text": "content"}},
        )

    index = pc.Index("quickstart")

    index.upsert_records(
        namespace="docs",
        records=[
            {"_id": "rec1", "content": "Refund requests must be submitted within 30 days."},
            {"_id": "rec2", "content": "All refunds are processed back to the original payment method."},
        ],
    )

    results = index.search(
        namespace="docs",
        query={"top_k": 5, "inputs": {"text": "refund policy"}},
        rerank={"model": "bge-reranker-v2-m3", "top_n": 3, "rank_fields": ["content"]},
    )

    return results
